document.addEventListener('DOMContentLoaded',()=>{
const t=document.querySelector('.menu-toggle'),n=document.querySelector('.nav');t?.addEventListener('click',()=>{const open=n.classList.toggle('open');t.setAttribute('aria-expanded',open)});document.querySelectorAll('.nav-drop>button').forEach(b=>b.addEventListener('click',e=>{if(innerWidth>1000)return;e.preventDefault();const d=b.parentElement;document.querySelectorAll('.nav-drop').forEach(x=>x!==d&&x.classList.remove('open'));d.classList.toggle('open');b.setAttribute('aria-expanded',d.classList.contains('open'))}));const f=document.querySelector('[data-project-form]');f?.addEventListener('submit',e=>{e.preventDefault();if(!f.checkValidity()){f.reportValidity();return}const data=new FormData(f),subject=encodeURIComponent(`Website inquiry: ${data.get('project')||'New project'}`),body=encodeURIComponent(`Name: ${data.get('name')}\nEmail: ${data.get('email')}\nOrganization: ${data.get('organization')}\nProject type: ${data.get('project')}\nBudget range: ${data.get('budget')}\nTimeline: ${data.get('timeline')}\n\nProject details:\n${data.get('message')}`);const s=document.querySelector('.form-status');s.textContent='Your email draft is ready. Please send it to start the conversation.';window.location.href=`mailto:info@ashitconsulting.ca?subject=${subject}&body=${body}`});
const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;document.documentElement.classList.add('motion-ready');const reveal=[...document.querySelectorAll('.section,.page-hero,.final-cta,.footer')];reveal.forEach((el,i)=>{el.classList.add('reveal');el.style.setProperty('--reveal-delay',`${Math.min(i%3,2)*70}ms`)});if(!reduced&&'IntersectionObserver'in window){const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('is-visible');observer.unobserve(entry.target)}}),{threshold:.12,rootMargin:'0px 0px -6%'});reveal.forEach(el=>observer.observe(el))}else reveal.forEach(el=>el.classList.add('is-visible'));
const cards=document.querySelectorAll('.cap-card,.engagement-card,.gov-card,.sector-tiles>div,.team-card');cards.forEach((card,i)=>{card.classList.add('lift-card');card.style.setProperty('--card-delay',`${i%4*65}ms`)});if(!reduced&&matchMedia('(pointer:fine)').matches)document.querySelectorAll('.cap-card,.engagement-card,.gov-card').forEach(card=>{card.addEventListener('pointermove',e=>{const r=card.getBoundingClientRect(),x=(e.clientX-r.left)/r.width-.5,y=(e.clientY-r.top)/r.height-.5;card.style.setProperty('--rx',`${-y*5}deg`);card.style.setProperty('--ry',`${x*6}deg`);card.classList.add('is-tilting')});card.addEventListener('pointerleave',()=>{card.classList.remove('is-tilting');card.style.removeProperty('--rx');card.style.removeProperty('--ry')})});
const orbit=document.querySelector('.grid-orbit'),signal=document.querySelector('.signal-card');if((orbit||signal)&&!reduced){let ticking=false;const update=()=>{const y=Math.min(scrollY,900);if(orbit)orbit.style.transform=`translate3d(0,${y*.1}px,0)`;if(signal)signal.style.transform=`translate3d(0,${y*-.055}px,0)`;ticking=false};addEventListener('scroll',()=>{if(!ticking){requestAnimationFrame(update);ticking=true}},{passive:true})}
});
